class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        size = t + 26
        dp = [1] * size
        for n in range(26, size):
            dp[n] = (dp[n - 26] + dp[n - 25]) % MOD
        total = 0
        for c in s:
            v = ord(c) - ord('a')
            total = (total + dp[t + v]) % MOD
        return total
class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        # Z[n] = length after n transformations starting from 'z'
        Z = [0] * (t + 1)
        def get(m):
            return 1 if m < 0 else Z[m]
        Z[0] = 1
        for n in range(1, t + 1):
            Z[n] = (get(n - 26) + get(n - 25)) % MOD
        total = 0
        for ch in s:
            v = ord(ch) - ord('a')
            k = t - (25 - v)
            total = (total + get(k)) % MOD
        return total
class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        N = t + 26
        dp = [1] * (N + 1)
        for n in range(26, N + 1):
            dp[n] = (dp[n - 26] + dp[n - 25]) % MOD
        total = 0
        for c in s:
            total += dp[t + ord(c) - ord('a')]
        return total % MOD

